TITLE = "GIẤU THÂN PHẬN BÊN NHAU BA NĂM, NGÀY ĐÍNH HÔN BỊ TRAO NHẪN CHO TIỂU TAM"

BEATS = [
    # --- MỞ MÀN (HOOK): Beats 1 - 6 ---
    ("0:00:02-0:00:35", "Giấu kín thân phận thiên kim tiểu thư độc nhất của tập đoàn nghìn tỷ để ở bên người yêu lập nghiệp suốt ba năm ròng rã, Thẩm Vân Chiêu cứ ngỡ ngày đính hôn sẽ là khoảnh khắc hái quả ngọt của tình yêu, nào ngờ chờ đợi cô lại là một màn sỉ nhục ngay trước mặt quan khách hai họ."),
    ("0:00:36-0:01:25", "Chỉ vì cô em gái thanh mai trúc mã Tô Hàm Yên vừa nhìn thấy chiếc nhẫn kim cương hồng thiết kế riêng đã buông lời xuýt xoa khen đẹp, vị hôn phu Cố Diễn Chi liền thản nhiên tháo ngay tín vật đính ước của vợ sắp cưới để đeo vào tay người phụ nữ khác."),
    ("0:01:26-0:02:15", "Khi Vân Chiêu cùng mẹ ruột lên tiếng đòi lại công bằng, gã đàn ông bội bạc chẳng những không thấy hổ thẹn mà còn quay sang trách cô nhỏ nhen ích kỷ, lạnh lùng buông lời rằng chỉ là một chiếc nhẫn vô tri, cho cô em gái mồ côi đeo thử một chút thì có mất miếng thịt nào đâu."),
    ("0:19:40-0:20:30,0:21:45-0:22:35", "Thế nhưng Cố Diễn Chi nằm mơ cũng chẳng thể ngờ được rằng, cô bạn gái luôn ăn mặc giản dị và lặng lẽ thức trắng đêm viết từng dòng mã nguồn cho hắn suốt ba năm qua, thực chất lại là em gái ruột của chủ tịch tập đoàn Thẩm thị quyền lực nhất thương trường."),
    ("0:23:30-0:24:30", "Và chính giây phút hắn ngạo mạn nắm tay nhân tình cắt chiếc bánh kem đính hôn, cũng là lúc Vân Chiêu dứt khoát đập nát hôn ước, rút sạch tám mươi triệu tệ vốn đầu tư lẫn toàn bộ bằng sáng chế cốt lõi, đẩy kẻ ăn cháo đá bát từ đỉnh cao danh vọng xuống thẳng vực sâu vạn trượng."),
    ("0:02:40-0:03:40", "Quay trở lại buổi sáng ngày diễn ra đại lễ đính hôn, bà Thẩm vì thương con gái rượu đã chịu nhiều thiệt thòi nên đích thân chuẩn bị sính lễ hồi môn hậu hĩnh gồm mười triệu tệ tiền mặt, căn hộ thông tầng đắt giá phía đông thành phố cùng hai chiếc siêu xe sang trọng."),

    # --- HỒI 1: TIỆC ĐÍNH HÔN TRƠ TRẼN & MÀN CẮT BÁNH LỊCH SỬ (Beats 7 - 22) ---
    ("0:03:41-0:04:35", "Vừa bước chân vào sảnh tiệc và nghe tin nhà gái tặng của hồi môn khổng lồ, mẹ con Cố Diễn Chi đã không giấu nổi vẻ mặt tham lam hớn hở, thế nhưng ngay khi nhìn thấy chiếc nhẫn kim cương hồng đặt trên đài lễ, Tô Hàm Yên lập tức giở trò đáng thương để xin đeo thử."),
    ("0:04:36-0:05:25", "Chiều chuộng cô em gái nuôi bất chấp lễ nghĩa, Cố Diễn Chi tự tay lồng chiếc nhẫn đính hôn của vị hôn thê vào ngón tay Hàm Yên, mặc kệ bà Thẩm giận dữ quát hỏi và Vân Chiêu đếm ngược ba tiếng bắt ả phải tháo trả ngay lập tức."),
    ("0:05:26-0:06:30", "Chưa dừng lại ở việc cướp nhẫn, khi vào bàn tiệc chính, mẹ con nhà họ Cố còn ngang nhiên xếp Tô Hàm Yên ngồi chễm chệ ở vị trí trung tâm vốn dành cho cô dâu, rồi ân cần gắp thức ăn tẩm bổ cho ả với lý do cô ả đang nắm giữ tài chính công ty nên rất vất vả."),
    ("0:06:31-0:07:35", "Trong khi để vị hôn thê thật sự phải ngồi lẻ loi một góc, Cố Diễn Chi lại dắt theo Tô Hàm Yên đi khắp các bàn rượu để ra mắt họ hàng nhà họ Thẩm, tự hào giới thiệu ả là cộng sự cốt lõi của Cố thị và xin các bậc trưởng bối nâng đỡ như người một nhà."),
    ("0:07:36-0:08:30", "Nhìn cảnh gã rể tương lai bỏ rơi cô dâu để dẫn một người phụ nữ không danh phận đi mời rượu, người cô ruột của Vân Chiêu không khỏi phẫn nộ mắng thẳng mặt, nhưng Cố Diễn Chi vẫn trơ trẽn cãi lại rằng hai nhà sắp kết thông gia thì Hàm Yên cũng tính là nửa người nhà họ Thẩm."),
    ("0:08:31-0:09:15", "Đến sát giờ cử hành hôn lễ, Tô Hàm Yên mới giả vờ nhăn nhó than rằng chiếc nhẫn bị kẹt cứng ở khớp tay không sao rút ra được, để rồi khi Vân Chiêu lạnh lùng vạch trần chỉ cần dùng một giọt nước rửa tay là tháo được ngay, Cố Diễn Chi lại lớn tiếng vu cho cô muốn bức chết Hàm Yên."),
    ("0:09:16-0:10:35", "Đỉnh điểm của sự vô liêm sỉ là ngay trước mặt toàn thể quan khách, Cố Diễn Chi còn nâng ly ép bà Thẩm phải nhận Tô Hàm Yên làm con gái nuôi để ả có chỗ dựa, khiến bà Thẩm đanh thép từ chối và các bậc trưởng bối nhà họ Thẩm đồng loạt tuyên bố sẽ làm chỗ dựa cho Vân Chiêu hủy hôn."),
    ("0:10:36-0:11:55", "Trong lúc lui vào hậu trường chuẩn bị, Tô Hàm Yên cố tình giả bộ bưng trà giúp rồi tự tay hất cả ấm nước sôi vào người Vân Chiêu để vu oan giá họa, vậy mà Cố Diễn Chi vừa lao tới đã mù quáng ôm lấy Hàm Yên xuýt xoa, còn quay sang mắng vị hôn thê của mình hậu đậu không biết giữ lễ."),
    ("0:11:56-0:13:25", "Đứng trước gương nhìn chiếc váy lễ phục ướt sũng cùng vết bỏng rát trên tay, bao nhiêu nhẫn nhịn suốt ba năm qua trong lòng Vân Chiêu hoàn toàn sụp đổ, cô tự nhủ đã đến lúc phải tự tay kết thúc vở kịch nực cười của những kẻ được đằng chân lân đằng đầu."),
    ("0:13:26-0:15:00", "Trở lại đại sảnh khi Tô Hàm Yên vẫn tiếp tục diễn trò đau đớn không tháo được nhẫn và dọa sẽ bỏ đi để kích động Cố Diễn Chi, Vân Chiêu chỉ nở nụ cười lạnh lẽo nhìn gã đàn ông đang hung hăng bảo vệ nhân tình mà chẳng buồn tranh cãi thêm một lời thừa thãi."),
    ("0:15:01-0:16:15", "Khi người dẫn chương trình xướng tên mời cô dâu chú rể lên sân khấu cắt chiếc bánh kem đồng tâm, Cố Diễn Chi lại làm ra một hành động chấn động cả hội trường khi thản nhiên kéo Tô Hàm Yên bước lên đài lễ, tuyên bố muốn giúp cô ả trọn vẹn giấc mơ chưa từng được tổ chức sinh nhật tử tế."),
    ("0:16:16-0:17:10", "Giữa tiếng xì xào bàn tán đầy phẫn nộ của quan khách bốn phía, Cố Diễn Chi vẫn nắm chặt bàn tay đeo nhẫn kim cương hồng của Tô Hàm Yên để cắt từng nhát xuống chiếc bánh đính hôn, còn mẹ hắn ở dưới lại vỗ tay khen con trai mình trọng tình trọng nghĩa."),
    ("0:17:11-0:18:25", "Không để gia tộc chịu thêm bất kỳ sự sỉ nhục nào nữa, Vân Chiêu dõng dạc bước lên tuyên bố hủy bỏ hôn ước ngay tại chỗ, khiến bà Cố hốt hoảng sợ mất khoản hồi môn mười triệu tệ nên vội vàng thúc giục con trai tháo nhẫn trả lại để giảng hòa."),
    ("0:18:26-0:19:35", "Đợi đến khi Cố Diễn Chi miễn cưỡng rút chiếc nhẫn từ tay nhân tình ra rồi quỳ xuống giục Vân Chiêu đeo vào để giữ thể diện cho hắn, cô chỉ nhìn món trang sức ấy bằng ánh mắt ghê tởm, dứt khoát khẳng định con gái nhà họ Thẩm không bao giờ dùng lại thứ đồ bẩn thỉu kẻ khác đã đeo."),
    ("0:19:36-0:21:25", "Đúng vào khoảnh khắc ấy, cánh cửa đại sảnh bật mở, chủ tịch tập đoàn Thẩm thị là Thẩm Vân Thâm dẫn theo đoàn vệ sĩ uy nghiêm sải bước tiến vào, thẳng tay hất văng chiếc nhẫn đính hôn xuống đất và lạnh lùng tuyên bố nhà họ Cố không xứng bước chân vào cửa hào môn."),
    ("0:21:26-0:22:38", "Cầm lấy chiếc micro trên sân khấu, Thẩm Vân Thâm chính thức công bố trước toàn thể giới truyền thông rằng Thẩm Vân Chiêu chính là em gái ruột duy nhất của anh, là vị đại tiểu thư kim chi ngọc diệp của đế chế Thẩm thị mà bấy lâu nay Cố Diễn Chi vẫn ngỡ chỉ là một cô gái bình thường."),

    # --- HỒI 2: CÔNG BỐ THÂN PHẬN, TÍNH SỔ BA NĂM & RÚT VỐN (Beats 23 - 38) ---
    ("0:22:39-0:23:30", "Cùng lúc đó, trợ lý đẩy lên sân khấu bản danh sách quỹ tín thác hai mươi triệu tệ cùng tám cuốn sổ đỏ bất động sản thương mại sầm uất, vốn là món quà bất ngờ mà Vân Chiêu định trao tặng cho Cố Diễn Chi trong ngày đính hôn nếu hắn giữ trọn tấm lòng chân thành."),
    ("0:23:31-0:24:25", "Nhìn khối tài sản khổng lồ bày ra trước mắt, mẹ con Cố Diễn Chi lập tức trở mặt nhanh hơn lật sách, rối rít nhận lỗi và bảo rằng mọi chuyện vừa rồi chỉ là thử thách tình cảm, nhưng đáp lại sự trơ trẽn ấy là lệnh rút toàn bộ vốn đầu tư và cắt đứt mọi hợp tác từ chủ tịch Thẩm Vân Thâm."),
    ("0:24:26-0:25:40", "Khi Cố Diễn Chi hoảng loạn cầu xin Vân Chiêu nói đỡ vì công ty Cố thị sắp sửa lên sàn chứng khoán, anh trai cô liền ném thẳng bằng chứng hắn biển thủ tiền của Thẩm gia để chuyển vào tài khoản cá nhân của Tô Hàm Yên mua nhà riêng, khiến cả hội trường cười chê kẻ tự tay đập vỡ bát cơm vàng."),
    ("0:25:41-0:27:30", "Sau khi đám khách khứa đã giải tán, Thẩm Vân Thâm ân cần trao lại cho em gái toàn bộ hồ sơ đầu tư và hệ thống kênh phân phối của Thẩm thị, khích lệ cô gái từng đạt giải nhất khởi nghiệp hãy bước ra ánh sáng làm chủ cuộc đời mình thay vì làm đá lót đường cho kẻ vô ơn."),
    ("0:27:31-0:28:38", "Thế nhưng một kẻ tự phụ như Cố Diễn Chi vẫn ảo tưởng rằng Vân Chiêu yêu mình sâu đậm suốt ba năm nên chỉ đang giận dỗi nhất thời, hắn ngang nhiên quay lại sảnh tiệc chặn đường, lớn tiếng trách cô bày trò tiểu thư để trêu đùa hắn rồi đòi ngồi xuống nói chuyện hòa giải."),
    ("0:28:39-0:29:35", "Trước thái độ ngạo mạn không biết hối cải của gã bạn trai cũ, Vân Chiêu quyết định mở sổ tính sạch từng khoản nợ suốt ba năm qua ngay trước mặt mọi người, từ năm triệu tệ tiền đặt cọc biệt thự tân hôn bị hắn lén lấy đi mua căn hộ độc thân cho Tô Hàm Yên, cho đến bằng sáng chế thuật toán cốt lõi bị hắn tự ý đổi tên."),
    ("0:29:36-0:30:45", "Ngay cả bản kế hoạch kinh doanh mà Vân Chiêu phải thức trắng đêm trong cơn sốt bốn mươi độ để hoàn thiện cũng bị hắn cướp công mang đi gọi vốn, còn những lúc cô nằm viện đau đớn một mình thì hắn lại bận đi tổ chức sinh nhật và đem hết thuốc bổ của mẹ cô gửi tặng sang cho nhân tình."),
    ("0:30:46-0:32:10", "Bị vạch trần từng chuyện xấu xa trước bàn dân thiên hạ, Tô Hàm Yên lại giở bài khóc lóc quỳ xuống nhận hết lỗi về mình, trong khi Cố Diễn Chi cũng vội vã quỳ sụp xuống xin lỗi, nhưng Vân Chiêu chỉ hỏi ngược một câu đanh thép rằng hắn đang quỳ trước cô hay đang quỳ trước khối tài sản của Thẩm gia."),
    ("0:32:11-0:33:30", "Thấy con trai mất mặt, bà Cố liền nhảy dựng lên kể công rồi nhận vơ Vân Chiêu là con dâu thảo, nhưng cô lập tức bóc mẽ chuyện bà ta từng chê cô nghèo hèn và bắt cô làm đủ mọi việc nhà cực nhọc với cái cớ rèn giũa tính nết, trước khi ra lệnh cho bảo vệ tống cổ cả bọn ra ngoài."),
    ("0:33:31-0:35:00", "Đứng bên ngoài bậc thềm, Cố Diễn Chi bị chạm tự ái liền lộ nguyên hình một kẻ tiểu nhân cay cú, gào lên rằng Vân Chiêu chẳng qua chỉ biết đầu thai vào nhà giàu, đồng thời vỗ ngực tuyên bố dù không có sự nâng đỡ của nhà họ Thẩm thì công ty Cố thị do hắn sáng lập vẫn sẽ thành công rực rỡ."),
    ("0:35:01-0:36:35", "Mặc cho bà Cố cuống cuồng bám theo chủ tịch Thẩm Vân Thâm để xin xỏ trong vô vọng, Cố Diễn Chi vẫn cố đuổi theo xe của Vân Chiêu để phân trần rằng Tô Hàm Yên mồ côi cha mẹ nên hắn không thể bỏ mặc, còn cô vốn dĩ mạnh mẽ và giàu có nên chẳng thiếu thốn thứ gì."),
    ("0:36:36-0:38:05", "Nghe thứ lý lẽ trịch thượng ấy, Vân Chiêu nhìn thẳng vào mắt hắn và hỏi lại rằng chẳng lẽ vì cô mạnh mẽ nên cô đáng phải chịu đựng một gã bạn trai thờ ơ lúc mình ốm đau, đáng phải nhường nhịn từ cổ phần công ty cho đến chiếc nhẫn đính hôn trong ngày trọng đại của đời mình hay sao."),
    ("0:38:06-0:39:22", "Khi bà Cố lao ra nắm chặt tay Vân Chiêu ăn vạ rằng nếu cô bỏ đi thì công ty của con trai bà sẽ ra sao, cô thẳng tay hất ra và lạnh lùng đáp trả rằng lúc hắn lấy tiền công ty mua nhà và sang tên cổ phần cho Tô Hàm Yên thì sao không tự hỏi công ty sẽ đi về đâu, rồi lên xe rời đi không một chút vương vấn."),
    ("0:39:23-0:41:50", "Trở về căn nhà của mình, bà Cố tiếc đứt ruột khoản hồi môn hàng chục triệu tệ vừa bay mất nên quay sang mắng chửi con trai và Tô Hàm Yên, để rồi sau đó cả ba lại chụm đầu bàn mưu tính kế bắt Cố Diễn Chi phải hạ mình cầu xin Vân Chiêu cưới trước nhằm nuốt trọn gia sản họ Thẩm về sau."),
    ("0:41:51-0:43:58", "Làm theo lời mẹ dặn, Cố Diễn Chi lập tức gọi điện cho Vân Chiêu thề thốt sẽ đòi lại nhà và cổ phần từ tay Tô Hàm Yên để trả cho cô, nhưng đáp lại hắn chỉ là giọng nói dửng dưng tuyên bố chuyện giữa hắn và ả thanh mai trúc mã giờ đây chẳng còn liên quan gì đến cuộc đời cô nữa."),
    ("0:43:59-0:45:45", "Tại biệt thự nhà họ Thẩm, chủ tịch Thẩm Vân Thâm chính thức phát đi thông báo hủy bỏ toàn bộ dự án chi nhánh định giao cho Cố thị, đồng thời cử luật sư Lục Tranh giám sát chặt chẽ mọi biến động tài chính để ngăn chặn mẹ con Cố Diễn Chi tẩu tán tài sản."),

    # --- HỒI 3: MẶT DÀY CẦU XIN, THU HỒI CÔNG TY & CÚ LỪA BÁN NHÀ (Beats 39 - 56) ---
    ("0:45:46-0:47:28", "Sáng hôm sau, Cố Diễn Chi vẫn tự tin xách cặp lồng cháo cá đến đứng trước cổng nhà họ Thẩm để diễn vai người tình si tâm, xin Vân Chiêu mười phút để giải thích chuyện chiếc nhẫn nhưng lại bị cô thẳng thừng chỉ rõ bản chất rằng hắn chưa bao giờ đặt cô ở vị trí quan trọng trong lòng."),
    ("0:47:29-0:48:45", "Thấy chiêu bài mềm mỏng thất bại, Cố Diễn Chi lập tức lật mặt đem giấy tờ mấy tòa nhà văn phòng đang đứng tên công ty ra làm con bài mặc cả, dọa nếu không có chữ ký của hắn thì nhà họ Thẩm đừng hòng sang tên, nào ngờ Thẩm Vân Thâm bước ra cảnh cáo thẳng về tội hình sự chiếm đoạt tài sản chưa qua công chứng."),
    ("0:48:46-0:50:45", "Bị bảo vệ ném ra khỏi cổng biệt thự, Cố Diễn Chi nghe theo lời xúi giục của mẹ chạy lên đường núi chặn đầu xe của bà Thẩm đang đi lễ Phật, quỳ rạp xuống đất tự tát vào mặt mình để cầu xin bà khuyên nhủ con gái, nhưng bà Thẩm chỉ lạnh nhạt buông một câu rồi bảo tài xế lái xe đi thẳng."),
    ("0:50:46-0:52:45", "Không còn cách nào khác, Cố Diễn Chi đành ép Tô Hàm Yên đến tận công ty quỳ xuống xin lỗi Vân Chiêu, thế nhưng vừa quỳ được vài giây thì cô ả đã ôm bụng kêu đau dữ dội để dụ hắn bế đi bệnh viện, rồi ngay khi hắn vừa quay lưng đi đóng viện phí thì ả liền rút điện thoại gọi môi giới bán gấp căn hộ ven sông."),
    ("0:52:46-0:54:02", "Trong lúc Cố Diễn Chi còn đang bận lo lắng cho màn kịch đau bụng của nhân tình ở phòng cấp cứu, Vân Chiêu đã dẫn theo đội ngũ pháp vụ và nhân viên tòa án cầm lệnh cưỡng chế đến thẳng trụ sở Cố thị, bất chấp bà Cố nằm ăn vạ trước cửa để thu hồi lại tòa nhà cùng toàn bộ hệ thống máy chủ."),
    ("0:54:03-0:55:20", "Khi Cố Diễn Chi hớt hải chạy về ôm chặt con dấu công ty và gào lên rằng đây là tâm huyết ba năm của mình, Vân Chiêu bình thản đưa ra hợp đồng tặng cho có điều kiện kèm theo hôn ước, đồng thời thông báo người đại diện pháp nhân đã được thay đổi hợp pháp từ một tiếng trước."),
    ("0:55:21-0:56:15", "Vừa bị tước lại con dấu và thẻ từ, tai họa tiếp theo đã ập xuống đầu Cố Diễn Chi khi ba ngân hàng lớn đồng loạt đóng băng tài khoản công ty và rút sạch hạn mức tín dụng năm mươi triệu tệ do tập đoàn Thẩm thị hủy bỏ bảo lãnh, khiến quỹ tiền mặt của Cố thị chỉ còn vỏn vẹn tám mươi ba vạn tệ."),
    ("0:56:16-0:57:08", "Giữa lúc các nhà cung cấp kéo đến đòi nợ ráo riết, Tô Hàm Yên liền ngọt nhạt nhắc tới căn hộ ven sông trị giá hơn mười triệu tệ đang đứng tên riêng của ả mà nhà họ Thẩm không thể kê biên, tình nguyện mang sổ đỏ đi thế chấp ngân hàng để lấy sáu bảy triệu tệ giúp hắn xoay vòng vốn."),
    ("0:57:09-0:58:25", "Cố Diễn Chi cảm động đến rơi nước mắt mà chẳng hề hay biết, ngay khi về tới căn hộ, Tô Hàm Yên đã cấu kết với tay giám đốc môi giới để bán đứt căn nhà với giá rẻ mạt tám triệu tệ, kèm điều kiện ngầm là người mua phải chuyển thẳng năm triệu tệ vào tài khoản nước ngoài của riêng ả."),
    ("0:58:26-0:59:50", "Hôm sau khi Cố Diễn Chi bất ngờ ghé qua căn hộ và bắt gặp khách đang xem nhà, Tô Hàm Yên liền nhanh trí bịa chuyện các ngân hàng đều từ chối cho Cố thị vay thế chấp nên ả đành phải cắn răng bán gấp trong ngày để lấy tiền mặt cứu hắn, khiến gã đàn ông ngu muội càng thêm biết ơn và hứa hẹn sẽ mua đền biệt thự lớn."),
    ("0:59:51-1:00:50", "Sau khi ký giấy sang tên xong xuôi, Tô Hàm Yên chỉ rút ra tờ ngân phiếu ba triệu tệ đưa cho Cố Diễn Chi với lý do bị khách ép giá và trừ phí sang tên khẩn cấp, rồi giả vờ dịu dàng tiễn hắn đem số tiền ít ỏi ấy về công ty xoay xở."),
    ("1:00:51-1:02:02", "Trớ trêu thay, tờ ngân phiếu ba triệu tệ vừa nạp vào tài khoản công ty Cố thị chưa kịp nóng chỗ đã bị hệ thống ngân hàng tự động khấu trừ ngay hai triệu tám trăm nghìn tệ tiền nợ quá hạn, cộng thêm chi phí điện nước máy chủ khiến số dư toàn công ty chỉ còn đúng bốn nghìn hai trăm tệ."),
    ("1:02:03-1:03:02", "Biết tin Thẩm tiểu thư đã thu hồi toàn bộ quyền truy cập thuật toán gốc và chuỗi vốn của công ty hoàn toàn đứt gãy, toàn bộ nhân viên phòng nghiên cứu đồng loạt đặt đơn từ chức cùng thẻ nhân viên lên bàn, mặc kệ Cố Diễn Chi gào thét vẽ bánh tăng lương hay dọa hủy quyền chọn cổ phiếu."),
    ("1:03:03-1:04:15", "Ôm hy vọng cuối cùng chạy đến buổi tiệc thương mại để xin quỹ đầu tư Hoa Nhĩ rót hai mươi triệu tệ đổi lấy bốn mươi phần trăm cổ phần, Cố Diễn Chi lại bị các nhà đầu tư cười nhạo thẳng mặt rằng rời khỏi Thẩm Vân Chiêu thì hắn đến một bản báo cáo tài chính hợp quy cũng không làm nổi, rồi bị bảo vệ thẳng tay ném ra cửa."),
    ("1:04:16-1:05:30", "Bị bảy quỹ đầu tư liên tiếp đuổi về và nhận thêm thông báo ngân hàng sắp niêm phong cả căn nhà cũ, bà Cố phát điên chụp lấy cây kéo lao thẳng đến biệt thự nhà họ Thẩm, tuyên bố sẽ đâm đầu tự vẫn trước cổng để bêu xấu danh tiếng hào môn nếu không đòi lại được công đạo cho con trai."),
    ("1:05:31-1:07:20", "Đứng trước cánh cổng sắt uy nghiêm của Thẩm gia, bà Cố vừa la lối đập phá vừa vu khống nhà giàu bắt nạt dân lành, nhưng chủ tịch Thẩm Vân Thâm chỉ lạnh lùng chỉ lên hệ thống camera giám sát đã kết nối trực tiếp với cơ quan tư pháp và báo cảnh sát đến còng tay bà ta ngay tại chỗ."),
    ("1:07:21-1:08:55", "Khi Cố Diễn Chi phải muối mặt đến đồn cảnh sát ký giấy bảo lãnh cho mẹ sau thời gian bị tạm giam hành chính, hai mẹ con không những không tỉnh ngộ mà còn quay sang cãi vã đổ lỗi cho nhau ngay trước mặt các cán bộ chấp pháp."),
    ("1:08:56-1:10:50", "Đêm hôm đó, trong lúc Cố Diễn Chi uống rượu trắng say mềm như bùn vì tuyệt vọng, Tô Hàm Yên ở bên cạnh liền lộ rõ bản chất rắn độc khi lục tung ngăn kéo lấy trộm mười vạn tệ tiền mặt cùng hai chiếc đồng hồ đắt giá của hắn, rồi trang điểm lộng lẫy đến khách sạn Vạn Hào tìm lão đại gia họ Triệu."),

    # --- HỒI 4: VÂN CHIÊU MỞ CÔNG TY TỶ ĐÔ & CÁI BẪY TÍN DỤNG ĐEN (Beats 57 - 74) ---
    ("1:10:51-1:11:45", "Sáng hôm sau trở về nhà với bát cháo trắng mua vội ngoài chợ, Tô Hàm Yên tỉnh bơ nói dối rằng mình vừa đi chợ sớm và đã nhờ bạn bè kết nối được với tổng giám đốc Triệu bên ngành ẩm thực để giúp hắn gọi vốn, khiến Cố Diễn Chi cảm động thề thốt cả đời này sẽ không phụ tấm chân tình của ả."),
    ("1:11:46-1:13:08", "Đúng lúc ấy, màn hình điện thoại đồng loạt phát sóng trực tiếp lễ ra mắt công ty Vân Chiêu Khoa Kỹ do chính Thẩm Vân Chiêu sáng lập, nơi cô công bố kiến trúc thuật toán thế hệ mới hoàn toàn vượt trội và nhận ngay đơn hàng năm mươi triệu tệ từ tập đoàn Hoằng Viễn cùng ba trăm triệu tệ vốn đầu tư từ quỹ Thẩm thị."),
    ("1:13:09-1:14:25", "Chứng kiến toàn bộ các đối tác lớn như Hoằng Viễn và Hoa Hưng đồng loạt hủy hợp đồng với Cố thị để chuyển sang ký kết độc quyền hàng trăm triệu tệ với Vân Chiêu, mẹ con Cố Diễn Chi tức đến đỏ mắt, thậm chí bà Cố còn xúi con trai cầm dao đi liều mạng còn Tô Hàm Yên thì âm thầm khích bác để hắn đi làm loạn."),
    ("1:14:26-1:15:45", "Đánh mất lý trí, Cố Diễn Chi phóng xe đến ngay sảnh tòa nhà Vân Chiêu Khoa Kỹ gào thét đòi chia một nửa bản quyền thuật toán rồi lao vào định hành hung Vân Chiêu, nhưng lập tức bị đội vệ sĩ quật ngã xuống sàn vì vi phạm lệnh cấm tiếp cận của tòa án."),
    ("1:15:46-1:16:58", "Đứng từ trên cao nhìn xuống kẻ đang giãy giụa dưới đất, Vân Chiêu ra lệnh cho luật sư Lục Tranh khởi động giai đoạn hai truy thu toàn bộ ba mươi triệu tệ nợ ngầm của Cố thị, đồng thời tống đạt thông báo khởi tố hình sự về tội xâm phạm thương mại và lừa đảo."),
    ("1:16:59-1:18:05", "Thẩm Vân Thâm cũng bước tới chỉnh lại cà vạt, đưa ra bằng chứng ba trăm hai mươi bằng sáng chế tầng đáy đều mang tên Vân Chiêu và cảnh cáo Cố Diễn Chi hãy tận hưởng những ngày tự do ngắn ngủi còn lại trước khi bước chân vào nhà giam."),
    ("1:18:06-1:19:30", "Trở về nhà đập phá đồ đạc trong cơn điên loạn vì trở thành trò cười cho toàn ngành, Cố Diễn Chi liền bị Tô Hàm Yên rót mật vào tai về một thương vụ buôn bán hạn ngạch thép nhập khẩu ở nước ngoài có thể giúp hắn nhân ba số vốn lên thành chín mươi triệu tệ chỉ trong vòng một tháng."),
    ("1:19:31-1:20:35", "Để lùa Cố Diễn Chi chui đầu vào rọ, Tô Hàm Yên giới thiệu hắn với đại ca Trương Long chuyên cho vay nặng lãi ở vùng ven biển với mức lãi hai phân một tháng, đồng thời khích tướng rằng chỉ cần thắng ván bài chín mươi triệu tệ này là hắn có thể đạp Thẩm Vân Chiêu dưới chân."),
    ("1:20:36-1:21:20", "Khi Cố Diễn Chi còn chút do dự sợ đứt chuỗi vốn, Tô Hàm Yên liền diễn màn kịch hy sinh cao cả khi tuyên bố đã đem toàn bộ tiền tiết kiệm riêng bỏ vào thương vụ này để cùng hắn đánh một trận sống còn, khiến hắn hoàn toàn sập bẫy và đồng ý đến phòng trà ký giấy vay."),
    ("1:21:21-1:22:10", "Bất chấp việc viện trọng tài lao động vừa gửi lệnh cưỡng chế lương nhân viên và tên của mình đã bị đưa vào danh sách đen tín dụng toàn ngành, Cố Diễn Chi vẫn ngạo mạn đuổi hết nhân viên đi vì đinh ninh tuần sau tài khoản sẽ có chín mươi triệu tệ."),
    ("1:22:11-1:23:35", "Tại phòng trà của Trương Long, dù biết rõ quy tắc cắt phế tàn nhẫn vay ba mươi triệu tệ nhưng thực nhận chỉ có hai mươi mốt triệu tệ kèm theo điều khoản chịu trách nhiệm liên đới vô hạn và điểm chỉ bằng máu, Cố Diễn Chi vẫn mù quáng ký tên vì giấc mộng đổi đời."),
    ("1:23:36-1:24:35", "Vừa cầm được khoản tiền vay nặng lãi trong tay, Cố Diễn Chi đã vội vã diện vest lẻn vào đêm tiệc thương hội của giới doanh nhân trăm tỷ để khoe khoang rằng tài khoản Cố thị vừa có ba mươi triệu tệ tiền mặt và sắp đạt định giá năm trăm triệu tệ."),
    ("1:24:36-1:25:35", "Nào ngờ ngay giữa sảnh tiệc, Vân Chiêu chỉ liếc qua mã giao dịch đã thẳng thừng bóc mẽ đó là nguồn tiền tín dụng đen của Trương Long bị cắt gần chục triệu tiền lãi đầu, khiến Cố Diễn Chi xấu hổ đến tột cùng và tiếp tục bị bảo vệ lôi cổ ném ra ngoài trước tiếng cười nhạo của giới thượng lưu."),
    ("1:25:36-1:27:12", "Vừa bị đuổi ra khỏi tiệc thì điện thoại báo tin dữ, sau khi trừ hết các loại phí cắt cổ, tài khoản chỉ còn mười lăm triệu tệ và toàn bộ số tiền đặt cọc ấy vừa chuyển vào công ty thương mại do anh họ Tô Hàm Yên giới thiệu thì văn phòng kia đã bốc hơi trong đêm, để lại pháp nhân là một cụ già chín mươi tuổi ở nông thôn."),
    ("1:27:13-1:28:15", "Khi Cố Diễn Chi còn chưa hết bàng hoàng trước cái bẫy công ty ma, đúng ngày đáo hạn, đám đàn em hung hãn của Trương Long đã đạp cửa xông vào nhà đòi cả gốc lẫn lãi ba mươi lăm triệu tệ, thẳng tay hành hung hai mẹ con hắn và tiết lộ sự thật động trời rằng chính Tô Hàm Yên đã nhận một triệu rưỡi tiền hoa hồng môi giới rồi cao chạy xa bay."),
    ("1:28:16-1:29:10", "Gọi điện cho Tô Hàm Yên chỉ nghe thấy tiếng báo thuê bao tắt máy, Cố Diễn Chi tuyệt vọng lao đến căn hộ từng mua cho ả để đòi sổ đỏ, nhưng người mở cửa lại là một người đàn ông lạ mặt cho biết đã mua đứt căn nhà này với đầy đủ thủ tục từ một tuần trước."),
    ("1:29:11-1:30:48", "Đứng chết trân trước hành lang khi nhận ra người phụ nữ mình bảo vệ suốt ba năm đã lừa gạt mình gánh khoản nợ ba mươi lăm triệu tệ để ôm tiền bỏ trốn, Cố Diễn Chi lại bị đám người của Trương Long đuổi kịp đánh đập dã man, lột sạch đồng hồ lẫn chìa khóa xe và dọa sẽ chặt tay nếu ngày mai không chồng đủ tiền."),
    ("1:30:49-1:32:40", "Trong lúc Cố Diễn Chi quỳ dưới đất gào khóc gọi tên Vân Chiêu cầu cứu, tại trụ sở tập đoàn Thẩm thị, tòa án nhân dân trung cấp đã chính thức phê duyệt lệnh bảo toàn tài sản và truy thu tám mươi triệu tệ đối với Cố thị, đồng thời Vân Chiêu cũng cho người âm thầm gửi hồ sơ ngoại tình của lão Triệu đến tận tay Triệu phu nhân."),

    # --- HỒI 5: MẸ CON CỐ THỊ SỤP ĐỔ, TÔ HÀM YÊN BỊ LỘT ĐỒ & TÒA TUYÊN BỐ PHÁ SẢN (Beats 75 - 92) ---
    ("1:32:41-1:34:05", "Do toàn bộ tài khoản và xe cộ của Cố Diễn Chi đã bị tòa án phong tỏa để ưu tiên thi hành án cho Thẩm thị, Trương Long không rút được một xu nào nên tức tối dẫn đàn em mang sơn đỏ đến hất kín cửa nhà họ Cố, dán tờ rơi con nợ khắp chung cư khiến hai mẹ con hắn phải tắt đèn trốn chui trốn lủi trong bóng tối."),
    ("1:34:06-1:35:25", "Đến khi trong nhà cạn sạch gạo và bị cắt cả điện nước, bà Cố phải lén lút ra phố mua vội nắm mì khô thì bất ngờ bắt gặp Tô Hàm Yên đang diện váy hiệu đắt tiền, tình tứ khoác tay lão đại gia họ Triệu bước ra từ cửa hàng trang sức kim cương."),
    ("1:35:26-1:36:55", "Cơn giận bốc lên tận đỉnh đầu, bà Cố lao tới túm chặt lấy Tô Hàm Yên đòi lại năm triệu tệ tiền bán nhà và tiền cứu mạng của con trai, nhưng ả trà xanh năm xưa từng khóc lóc gọi bà là mẹ giờ đây lại thẳng chân đạp bà ngã nhào xuống đất, gọi bà là bà già ăn mày điên loạn và sai vệ sĩ của lão Triệu đánh đuổi."),
    ("1:36:56-1:38:20", "Giữa đám đông người qua đường đang giơ điện thoại quay phim, Tô Hàm Yên không ngần ngại cười khẩy tuyên bố những khoản tiền kia đều do Cố Diễn Chi ngu xuẩn tự nguyện dâng tặng, thậm chí còn sỉ nhục hắn chỉ là một gã bất tài ăn bám nhà họ Thẩm, rời khỏi Thẩm Vân Chiêu thì chẳng bằng một con chó."),
    ("1:38:21-1:39:25", "Nhìn ả nhân tình của con trai nghênh ngang bước lên xe sang đi xem căn hộ tầng thượng cùng gã đàn ông đáng tuổi cha chú, bà Cố uất ức đến mức thổ huyết ngay giữa đường và được đưa đi cấp cứu trong khi đoạn video ả trà xanh lật mặt nhanh chóng leo lên vị trí số một bảng tìm kiếm."),
    ("1:39:26-1:40:45", "Xem đoạn video Tô Hàm Yên mắng mình là kẻ ăn bám trên mạng xã hội, Cố Diễn Chi phát điên đập nát đồ đạc rồi hớt hải chạy vào bệnh viện khi nghe tin mẹ nguy kịch, nhưng vì toàn bộ thẻ ngân hàng đã bị đóng băng nên hắn chỉ biết quỳ xuống cầu xin bác sĩ cho ký giấy nợ viện phí."),
    ("1:40:46-1:41:55", "Nào ngờ ngay tại hành lang phòng cấp cứu, Trương Long đã lần theo tin tức trên mạng tìm tới nơi, đè Cố Diễn Chi xuống đất ép điểm chỉ vào bản cam kết hiến tạng trừ nợ ba mươi lăm triệu tệ nếu không sẽ rút ống thở của mẹ hắn ngay lập tức, đúng lúc cảnh sát hình sự ập vào bắt giữ toàn bộ băng nhóm tín dụng đen."),
    ("1:41:56-1:43:22", "Khi nghe cảnh sát cho biết tập đoàn Thẩm thị đã cung cấp chứng cứ hỗ trợ chuyên án quét sạch băng nhóm của Trương Long, Cố Diễn Chi lại ảo tưởng rằng Vân Chiêu vẫn còn nặng tình với mình nên vội lao ra cổng bệnh viện đuổi theo đoàn xe của cô dưới trời mưa, nhưng chiếc xe sang chỉ lướt qua lạnh lùng không một lần ngoảnh lại."),
    ("1:43:23-1:44:55", "Cùng thời điểm đó, tại căn hộ ngắm sông của lão Triệu, Triệu phu nhân dẫn theo đội ngũ công chứng viên cùng luật sư của tập đoàn Thẩm thị phá khóa xông thẳng vào phòng ngủ, bắt quả tang đôi gian phu dâm phụ và tát thẳng vào mặt kẻ dám dùng ba trăm triệu tệ tài sản chung của bà để bao nuôi nhân tình."),
    ("1:44:56-1:46:18", "Đứng trước bản sao kê dòng tiền do pháp vụ Thẩm thị cung cấp, lão Triệu sợ vợ đến mức vội vã đá văng Tô Hàm Yên sang một bên và mắng ả là con đĩ đào mỏ, trong khi Triệu phu nhân thông báo năm căn nhà và hai chiếc xe sang đứng tên ả đã bị phong tỏa toàn bộ rồi ra lệnh lột sạch quần áo trang sức trên người ả."),
    ("1:46:19-1:47:30", "Chưa dừng lại ở đó, luật sư của Thẩm thị còn công bố kết quả điều tra dòng tiền cho thấy trong ba mươi lăm triệu tệ mà Cố thị biển thủ có tới mười hai triệu tệ chảy thẳng vào túi Tô Hàm Yên qua hợp đồng vay giả tạo, cấu thành tội lừa đảo và chiếm đoạt tài sản có tổ chức."),
    ("1:47:31-1:49:20", "Bị lột sạch đồ hiệu ném ra khỏi khu chung cư cao cấp và bị liệt vào danh sách thất tín toàn quốc, Tô Hàm Yên chạy về căn phòng thuê cũ thì bị chủ nhà thay khóa ném thẳng hai chiếc rương hành lý vào thùng rác ven đường, khiến ả chỉ biết ngồi bệt bên đống rác gào khóc thảm thiết."),
    ("1:49:21-1:50:50", "Tại phiên tòa xét xử phá sản, bất chấp Cố Diễn Chi van xin cơ hội tái cơ cấu, luật sư trình bày rõ toàn bộ công nghệ cốt lõi đều thuộc sở hữu của Thẩm thị và Cố thị đã rơi vào tình trạng nợ gấp ba lần tài sản với khoản biển thủ tám mươi tư triệu tệ, để rồi thẩm phán gõ búa tuyên bố Cố thị chính thức phá sản."),
    ("1:50:51-1:52:00", "Bước ra khỏi phòng xử án, Cố Diễn Chi vẫn cố lao tới cầu xin Vân Chiêu cho mình vay năm triệu tệ để làm lại từ đầu và nhắc lại tình nghĩa ba năm, nhưng cô chỉ nhìn hắn bằng ánh mắt khinh bỉ dành cho một con ký sinh trùng tham lam trước khi quay lưng đến dự tiệc mừng công cùng hội đồng quản trị."),
    ("1:52:01-1:53:35", "Ngay sau phiên tòa, lệnh hạn chế tiêu dùng cao và danh sách con nợ thất tín của Cố Diễn Chi được công bố rộng rãi, đội thi hành án lập tức đến dán niêm phong căn nhà cuối cùng bất chấp bà Cố vừa xuất viện đã phát điên lao vào xé giấy niêm phong."),
    ("1:53:36-1:55:00", "Bị đuổi ra đường giữa cơn mưa tầm tã khi thần trí đã hoàn toàn loạn lạc, bà Cố vừa đi vừa cười ngây dại dưới mưa, miệng không ngừng gào thét rằng con trai mình là tổng tài trăm tỷ và bắt Thẩm Vân Chiêu phải mang đoàn xe rước dâu đến quỳ dâng nước rửa chân cho bà."),
    ("1:55:01-1:56:20", "Dắt người mẹ điên loạn về tá túc trong một căn phòng trọ ẩm mốc đầy chuột bọ với vỏn vẹn ba trăm tệ tiền mặt trong túi đến tiền mua thuốc cũng không đủ, Cố Diễn Chi bị mẹ ruột tưởng nhầm là ma quỷ nhà họ Thẩm đến đòi mạng nên vồ lấy cắn xé, buộc hắn phải nuốt nước mắt đi làm thuê ban đêm."),
    ("1:56:21-1:57:22", "Gã tổng tài từng quen ăn trên ngồi trốc ngày nào giờ phải khoác chiếc tạp dề nhân viên cửa hàng tiện lợi với mức lương hai mươi tệ một giờ, còng lưng bê từng thùng nước khoáng nặng trịch suốt đêm dưới sự quát tháo và dọa trừ lương của người quản lý."),

    # --- HỒI 6: ĐỈNH CAO CỦA VÂN CHIÊU vs. KIẾP CHẠY XE ÔM CỦA CỐ DIỄN CHI (Beats 93 - 110) ---
    ("1:57:23-1:59:45", "Trái ngược hoàn toàn với cảnh khuân vác khốn cùng của Cố Diễn Chi, tại đại tiệc vinh danh thương giới, kiến trúc thuật toán của Vân Chiêu Khoa Kỹ xuất sắc giành giải thưởng đặc biệt, bà Thẩm và anh trai trang trọng trao ấn ngọc truyền thống ba đời cùng hàng chục tỷ nghiệp vụ hải ngoại để cô chính thức nhậm chức Chủ tịch."),
    ("1:59:46-2:01:45", "Đúng lúc màn hình tivi trong cửa hàng tiện lợi đang phát sóng cảnh Chủ tịch Thẩm Vân Chiêu nâng ly rượu mừng trăm tỷ, mấy nhân viên cũ từng bị Cố Diễn Chi nợ lương tình cờ bước vào mua nước, nhận ra vị sếp cũ đang mặc tạp dề bốc vác liền rút điện thoại quay lại tung lên mạng khiến ông chủ cửa hàng lập tức sa thải hắn không trả một đồng lương."),
    ("2:01:46-2:03:00", "Bị đuổi việc giữa đêm với bàn chân bầm dập và trong túi chỉ còn bảy mươi tệ không đủ mua nổi nửa hộp thuốc thần kinh cho mẹ, Cố Diễn Chi đành cắn răng thuê một chiếc xe máy điện cũ nát với giá hai mươi tệ một ngày để lao vào màn mưa bão chạy giao hàng ban đêm."),
    ("2:03:01-2:03:48", "Vì đường ngập nước và tay lái run rẩy, chiếc xe điện của hắn trượt ngã sõng soài giữa vũng bùn, làm đổ nát thố súp Phật nhảy tường trị giá tám trăm tệ của khách, khiến hắn không những không kiếm được đồng nào mua thuốc mà tài khoản giao hàng còn bị phạt âm chín trăm tệ."),
    ("2:03:49-2:05:15", "Thê thảm hơn, hôm sau khi hai mẹ con hắn đang đi nhặt vỏ chai nhựa bên bãi rác thì đụng độ Tô Hàm Yên cũng đang phải đi nhặt phế liệu kiếm sống, bà Cố lên cơn điên liền vồ lấy ả cắn xé rồi vớ gạch đập thẳng vào đầu kẻ đã lừa sạch gia sản của con trai mình."),
    ("2:05:16-2:07:30", "Cả ba kẻ khốn cùng lao vào cấu xé nhau đến đầu rơi máu chảy và bị cảnh sát điệu thẳng về đồn, tại đây Tô Hàm Yên vì liên quan đến hàng loạt vụ án chiếm đoạt tài sản và gây rối trật tự nên bị trục xuất khỏi thành phố với tấm vé xe cứu trợ, còn Cố Diễn Chi tiếp tục cõng người mẹ điên lang thang khắp đầu đường xó chợ."),
    ("2:07:31-2:10:25", "Khi Cố Diễn Chi đang đẩy chiếc xe điện hỏng phanh đi qua quảng trường Thời Đại, màn hình LED khổng lồ tám trăm mét vuông bất ngờ chiếu rọi gương mặt và thông tin nợ tám mươi tư triệu tệ của hắn trong chuyên mục bêu tên con nợ thất tín, khiến người đi đường chỉ trỏ xôn xao và cảnh sát giao thông lập tức giữ lại thu hồi tài khoản chạy xe đăng ký chui."),
    ("2:10:26-2:12:25", "Tại biệt thự nhà họ Thẩm, sau khi toàn bộ nhà cửa xe cộ của Cố Diễn Chi đã được bán đấu giá, khoản nợ còn thiếu năm mươi sáu triệu tệ được chuyển vào hệ thống truy thu trọn đời tự động khấu trừ mọi thu nhập hợp pháp của hắn, để gia đình Vân Chiêu thảnh thơi nâng bát canh hầm sáu tiếng mừng ngày quét sạch rác rưởi."),
    ("2:12:26-2:13:18", "Đứng bên ngọn lửa hóa vàng, Vân Chiêu bình thản châm lửa đốt cháy tấm thiệp hồng đính hôn của ba năm trước thành tro bụi, chính thức khép lại bài học nhìn người để sẵn sàng bước lên diễn đàn Hội nghị Thượng đỉnh Lãnh đạo Thương mại Quốc tế."),
    ("2:13:19-2:15:35", "Trong khi đó, Cố Diễn Chi không còn tài khoản chạy xe nên phải đi xin đồng nghiệp một bát cháo trắng mang về phòng trọ, nhưng vừa bưng đến nơi đã bị người mẹ điên hất đổ bỏng rát cả tay rồi cầm gậy đánh đập bắt hắn phải đi đòi lại gia sản trăm tỷ của nhà họ Thẩm."),
    ("2:15:36-2:18:02", "Tại trung tâm hội nghị quốc tế, dưới sự chứng kiến của năm mươi tập đoàn đầu tư hàng đầu, Thẩm Vân Chiêu tự tin bước lên bục diễn thuyết công bố mở rộng ba trăm bằng sáng chế cốt lõi để thiết lập trật tự mới cho toàn ngành, ngay lập tức thu về bản hợp đồng đầu tư hai trăm tỷ tệ."),
    ("2:18:03-2:19:40", "Trớ trêu thay, người tài xế giao hàng đang ướt sũng bùn đất, phải chạy bộ dưới mưa vì đứt dây phanh để kịp giao bó hoa hồng dát vàng mừng lễ cho trung tâm hội nghị trước mười hai giờ trưa, lại chính là Cố Diễn Chi."),
    ("2:19:41-2:22:05", "Đứng chết lặng dưới sảnh tòa nhà nhìn hình ảnh Vân Chiêu rạng rỡ trên màn hình lớn với định giá công ty vượt hàng chục tỷ và nghe những người xung quanh bàn tán về gã bạn trai cũ mù mắt năm xưa, Cố Diễn Chi bật khóc nức nở trong sự hối hận muộn màng khi bên trong hội trường đang cử hành lễ hợp nhất chiến lược và bổ nhiệm Vân Chiêu làm Đồng Chủ tịch tập đoàn Thẩm thị."),
    ("2:22:06-2:24:05", "Ôm bó hoa dát vàng của tập đoàn đa quốc gia gửi tặng mò lên tận tầng thượng, Cố Diễn Chi làm bẩn cả tấm thảm thủ công đắt tiền trước cửa phòng tiệc và bị đội bảo vệ chặn lại, mặc cho hắn gào thét rằng mình từng yêu Chủ tịch Thẩm suốt ba năm để xin được vào gặp mặt một lần."),
    ("2:24:06-2:26:10", "Nhìn qua khe cửa thấy Vân Chiêu trong bộ lễ phục lộng lẫy đang nâng ly rượu mừng cùng các bậc trưởng bối và giới tinh hoa thương trường, Cố Diễn Chi cố sống cố chết vùng vẫy gọi tên cô trong tuyệt vọng nhưng chỉ bị đội vệ sĩ bịt miệng kéo lê vào thang máy như một thứ rác rưởi."),
    ("2:26:11-2:27:58", "Bị ném ra sảnh trước mặt các vị tổng giám đốc đang dự tiệc, Cố Diễn Chi lấm lem bùn đất quỳ bò dưới sàn cầu xin Thẩm Vân Thâm và Vân Chiêu thưởng cho mình một miếng cơm ăn, thậm chí tình nguyện làm chó giữ cửa cho nhà họ Thẩm, khiến Vân Chiêu dừng bước bảo vệ sĩ buông tay để nghe hắn nói nốt lời cuối."),
    ("2:27:59-2:29:48", "Khi Cố Diễn Chi vẫn ngây thơ hỏi rằng có phải cô vẫn còn chút lưu luyến không nỡ bỏ mặc hắn hay không, Vân Chiêu cùng bà Thẩm chỉ nhìn hắn bằng ánh mắt phẳng lặng như nhìn một người xa lạ, chỉ thẳng ra sai lầm lớn nhất đời hắn chính là chưa bao giờ tự nhận thức được bản thân mình là ai khi rời khỏi cái bóng của Thẩm gia."),
    ("2:29:49-2:31:18", "Nâng ly rượu sâm panh lấp lánh trên tay, Vân Chiêu dõng dạc tuyên bố ly rượu này cô kính tất cả những người trọng chữ tín trên thương trường, còn kẻ bội bạc trước mặt thì vĩnh viễn không xứng đáng, rồi ra lệnh cho bảo vệ đóng sập cánh cửa đại sảnh lại trước mặt hắn."),

    # --- HỒI KẾT: ÁN TÙ CHO KẺ ĐÀO MỎ & CÁI KẾT CỦA KẺ BỘI BẠC (Beats 111 - 120) ---
    ("2:31:19-2:32:45", "Quỳ sụp trước cánh cửa đại sảnh đã khép chặt dưới cơn mưa tầm tã, Cố Diễn Chi tự tát vào mặt mình trong nỗi ân hận xé lòng, nhưng Thẩm Vân Thâm bước ra chỉ lạnh lùng nhắn nhủ rằng cánh cửa này chính tay hắn đã tự đóng lại từ ngày đính hôn ba năm trước."),
    ("2:32:46-2:34:35", "Ngay sau đó, xe cảnh sát hú còi lao tới trước sảnh trung tâm hội nghị, còng tay Cố Diễn Chi đưa thẳng về trại giam vì tội gây rối tại sự kiện quốc tế và trốn tránh thi hành bản án nợ nần đã có hiệu lực pháp luật."),
    ("2:34:36-2:35:25", "Còn về phần bà Cố, người đàn bà từng hống hách đòi con dâu tương lai hầu hạ giờ đây hoàn toàn mất trí nhớ, suốt ngày lang thang trong ngôi làng đổ nát gào đòi vòng vàng nhẫn ngọc trước sự chế giễu của hàng xóm láng giềng."),
    ("2:35:26-2:36:18", "Về phía ả trà xanh Tô Hàm Yên, sau khi bị trục xuất và rơi vào cảnh đường cùng, ả xin vào làm nhân viên tại một tiệm rửa xe rồi lén lút ăn cắp mười vạn tệ tiền mặt trong xe của khách, để rồi bị bắt quả tang tại trận."),
    ("2:36:19-2:37:24", "Do có tiền án lừa đảo và thái độ ngoan cố đổ tội cho người khác, tòa án tuyên phạt Tô Hàm Yên ba năm tù giam, khép lại giấc mộng đổi đời của ả đào mỏ đằng sau song sắt nhà lao lạnh lẽo."),
    ("2:37:25-2:38:02", "Giữa lúc những kẻ phản bội phải trả giá đắt cho lòng tham của mình, tạp chí danh giá toàn cầu chính thức công bố danh sách Lãnh đạo Trẻ xuất sắc nhất châu Á với vị trí quán quân thuộc về Chủ tịch Thẩm Vân Chiêu, người đã đưa tập đoàn Thẩm thị lọt vào nhóm mười đế chế thương mại hàng đầu thế giới."),
    ("2:38:03-2:38:28", "Sải bước đầy kiêu hãnh trên bậc thềm trụ sở tập đoàn giữa sự tháp tùng của anh trai và đội ngũ trợ lý cấp cao, Vân Chiêu điềm nhiên khẳng định cô không hề đi giành giật lại thứ gì, mà chỉ đơn giản là đưa tất cả những con người và vị trí từng bị đặt sai chỗ trở về đúng quỹ đạo của nó."),
    ("2:38:29-2:38:55", "Đúng khoảnh khắc đoàn xe sang trọng của Chủ tịch Thẩm chuẩn bị lăn bánh đến buổi tiệc ký kết đa quốc gia, phía bên kia đường, Cố Diễn Chi sau khi mãn hạn tạm giam lại đang lê bước đẩy chiếc xe điện đứt phanh với ba mươi tệ tiền công ít ỏi vừa kiếm được trong ngày."),
    ("2:38:56-2:39:14", "Ngước nhìn bóng dáng rạng rỡ và cao quý của người con gái từng hết lòng yêu thương mình lướt qua sau lớp kính xe sang, gã đàn ông rách rưới chỉ biết đứng chôn chân giữa phố đông mà chẳng còn dám cất tiếng gọi tên."),
    ("2:39:05-2:39:31,2:37:45-2:38:15", "Giữa làn gió lạnh buốt chiều tà, Cố Diễn Chi gục đầu rơi nước mắt, cay đắng thừa nhận rằng viên minh châu vô giá ấy chính tay hắn đã tự mình đánh mất. Câu chuyện khép lại với bài học đắt giá rằng trong tình yêu cũng như cuộc đời, sự bao dung chỉ nên dành cho người biết trân trọng, còn với kẻ vô ơn bội nghĩa thì buông tay đúng lúc chính là sự trả thù rực rỡ nhất."),
]
